message.content:
{
  "pitches": [
    {
      "key": "gehenna_ar_calculation",
      "title": "악당의 품격과 계산서",
      "premise": "아루가 멋진 악당답게 당당하게 계산을 하겠다고 큰소리치며 계산서를 집어 든다. 무츠키는 아루의 허세를 눈치채고 비웃으며 여행자를 쳐다본다. 여행자는 아루의 허세를 돕거나, 무츠키의 조롱에 반응하거나, 아루의 계산을 대신 확인해야 한다.",
      "choices": [
        "아루의 멋진 포즈에 맞춰 계산을 도와준다.",
        "무츠키의 비웃음에 동조하며 아루를 곤란하게 만든다.",
        "아루의 허세를 진지하게 받아들이며 계산이 맞는지 꼼꼼히 확인한다."
      ],
      "basis": "아루의 허술한 악당 연기와 무츠키의 장난스러운 성격이 충돌하는 상황을 묘사한다."
    },
    {
      "key": "gehenna_kayoko_order",
      "title": "침묵과 오해의 주문",
      "premise": "카요코가 주문을 하려 하지만, 가게 주인이 그녀의 무서운 인상 때문에 겁을 먹고 주춤한다. 카요코는 당황하며 입을 닫고, 여행자 옆에서 눈치를 본다. 여행자는 카요코를 대신해 주문을 말하거나, 그녀가 말할 때까지 기다려주거나, 주인에게 상황을 설명해야 한다.",
      "choices": [
        "카요코 대신 부드러운 목소리로 주문을 전달한다.",
        "카요코가 말할 수 있게 옆에서 조용히 기다려준다.",
        "주인에게 카요코는 무서운 사람이 아니라고 안심시킨다."
      ],
      "basis": "카요코의 외모로 인한 오해와 여행자의 중재를 다루는 일상적인 갈등이다."
    },
    {
      "key": "gehenna_haruka_weed",
      "title": "잡초와 소중한 화분",
      "premise": "여행자가 무심코 잡초라고 생각한 식물을 치우려 하자 하루카의 손이 파르르 떨린다. 하루카는 자존감이 낮은 듯 고개를 숙이고 당황스러운 표정을 짓는다. 여행자는 자신의 실수를 사과하거나, 식물을 옮겨줄 자리를 내주거나, 하루카와 함께 식물을 관찰해야 한다.",
      "choices": [
        "실수를 바로 인정하고 사과하며 식물을 원래 자리에 둔다.",
        "식물이 잘 자랄 수 있는 더 좋은 자리를 함께 고민해준다.",
        "하루카의 말에 귀를 기울이며 식물의 이름을 함께 물어본다."
      ],
      "basis": "하루카의 돌발적인 감정과 소중한 것을 지키려는 성격을 반영한다."
    },
    {
      "key": "gehenna_mutsuki_bet",
      "title": "작은 내기와 대가",
      "premise": "무츠키가 아루를 놀린 뒤 여행자에게도 가벼운 내기를 제안하며 짓궂게 웃는다. 내기의 내용은 사소하지만 결과에 따라 여행자가 무츠키의 장난을 받아내야 하는 상황이다. 여행자는 내기에 응하거나, 확실한 대가를 치르거나, 무츠키의 제안을 정중히 거절해야 한다.",
      "choices": [
        "무츠키의 내기에 응해 결과에 따른 장난을 받아들인다.",
        "내기 대신 무츠키가 원하는 작은 간식이나 물건을 대가로 준다.",
        "무츠키의 장난이 과하다고 말하며 단호하게 거절한다."
      ],
      "basis": "무츠키의 장난스러운 성격과 여행자의 대응을 대조한다."
    },
    {
      "key": "gehenna_hina_inspection",
      "title": "엄격한 검문과 오해",
      "premise": "히나가 앞을 가로막으며 검문을 실시하자, 여행자는 옆 사람의 소지품 때문에 검문받는다고 오해한다. 히나는 매우 냉정하고 신속하게 주변을 살피며 규정을 확인한다. 여행자는 히나에게 상황을 설명하거나, 검문을 묵묵히 견디거나, 옆 사람에게 도움을 요청해야 한다.",
      "choices": [
        "히나에게 상황을 설명하고 오해를 바로잡는다.",
        "히나의 엄격함을 받아들이며 묵묵히 검문을 견딘다.",
        "옆 사람에게 다가가 함께 상황을 해결해달라고 부탁한다."
      ],
      "basis": "히나의 공무적이고 냉정한 성격과 여행자의 당혹감을 묘사한다."
    },
    {
      "key": "trinity_hifumi_promise",
      "title": "휘말린 약속의 확인",
      "premise": "히후미가 흥신소의 부탁에 호의적으로 대답하다가, 자신이 원래 하려던 계획과 충돌함을 깨닫고 당황한다. 그녀는 여행자에게 미안해하며 어떻게 해야 할지 묻는다. 여행자는 히후미를 도와 우선순위를 정해주거나, 원래 계획을 고수하게 하거나, 함께 대안을 찾아야 한다.",
      "choices": [
        "히후미가 원래 하려던 계획을 먼저 처리하도록 돕는다.",
        "흥신소의 부탁을 우선으로 처리하도록 설득한다.",
        "두 가지를 동시에 해결할 수 있는 절충안을 함께 고민한다."
      ],
      "basis": "히후미의 온화하지만 분위기에 휩쓸리는 성격을 반영한 대화형 사건이다."
    }
  ]
}
